# Evolution stages are already included in the EVOLUTION_STAGES dict below

# Experience Groups with proper Gen 1 formulas
def _calculate_exp_fast(level):
    return int((4 * (level ** 3)) / 5)

def _calculate_exp_medium_fast(level):
    return int(level ** 3)

def _calculate_exp_medium_slow(level):
    return int((6/5) * (level ** 3) - 15 * (level ** 2) + 100 * level - 140)

def _calculate_exp_slow(level):
    return int((5 * (level ** 3)) / 4)

EXP_GROUPS = {
    "fast": _calculate_exp_fast,
    "medium_fast": _calculate_exp_medium_fast,
    "medium_slow": _calculate_exp_medium_slow,
    "slow": _calculate_exp_slow
}

